insert into public.docs(path,data) values
  ('courses/ex-blooms', '{"createdAt": 1792330000003, "description": "Debate, present and write so people listen.", "hue": 1, "langCode": "en", "language": "English", "level": "Blooms", "sample": true, "title": "Speak Up"}'::jsonb),
  ('courses/ex-seeds', '{"createdAt": 1792330000001, "description": "Sing, dance and say your first English words: hello, colours, animals and numbers.", "hue": 4, "langCode": "en", "language": "English", "level": "Seeds", "sample": true, "title": "First Words"}'::jsonb),
  ('courses/ex-sprouts', '{"createdAt": 1792330000002, "description": "Go on word quests, read short stories and build sentences of your own.", "hue": 0, "langCode": "en", "language": "English", "level": "Sprouts", "sample": true, "title": "Word Quests"}'::jsonb),
  ('lessons/ex-b1', '{"body": "Good speakers look up, speak slowly and pause after important points.\n\nRecord yourself giving a one-minute talk on your favourite place. Listen back once.", "courseId": "ex-blooms", "kind": "speak", "mediaUrl": "", "minutes": 25, "order": 1, "title": "Say it with confidence", "vocab": "confident = आत्मविश्वासी\nopinion = राय\nbecause = क्योंकि\nexample = उदाहरण"}'::jsonb),
  ('lessons/ex-b2', '{"body": "In a debate, you say what you think and give a reason. \"I agree, because…\" \"I disagree, because…\"\n\nPick a topic: \"Homework should be optional.\" Write two reasons for each side.", "courseId": "ex-blooms", "kind": "speak", "mediaUrl": "", "minutes": 25, "order": 2, "title": "Agree or disagree?", "vocab": "agree = सहमत\ndisagree = असहमत\nreason = कारण\nhowever = फिर भी"}'::jsonb),
  ('lessons/ex-p1', '{"body": "Drizzle the cloud made a big puddle. Buzz wanted to jump in, but Pip said, \"Wait! Let''s look first.\"\n\nRead the story aloud. Then tell a grown-up what you would do at the puddle.", "courseId": "ex-sprouts", "kind": "story", "mediaUrl": "", "minutes": 20, "order": 1, "title": "The puddle quest", "vocab": "puddle = पानी का गड्ढा\njump = कूदना\nsplash = छपाका\ncareful = सावधान"}'::jsonb),
  ('lessons/ex-p2', '{"body": "A sentence needs someone and something they do. \"Pip jumps.\" \"Buzz flies.\"\n\nMake three sentences about your family.", "courseId": "ex-sprouts", "kind": "game", "mediaUrl": "", "minutes": 15, "order": 2, "title": "Build a sentence", "vocab": "jumps = कूदता है\nflies = उड़ता है\nreads = पढ़ता है\nsings = गाता है"}'::jsonb),
  ('lessons/ex-s1', '{"body": "Pip the seed says hello! Wave and say hello back.\n\nSing the hello song with a grown-up. Each time you hear \"hello\", wave your hand.", "courseId": "ex-seeds", "kind": "song", "mediaUrl": "", "minutes": 10, "order": 1, "title": "Hello, Pip!", "vocab": "hello = नमस्ते\ngoodbye = अलविदा\nthank you = धन्यवाद\nplease = कृपया"}'::jsonb),
  ('lessons/ex-s2', '{"body": "Look around your home. Can you find something red like Buzz? Something green like Pip? Something yellow like the sun?\n\nPoint and say the colour out loud.", "courseId": "ex-seeds", "kind": "game", "mediaUrl": "", "minutes": 15, "order": 2, "title": "Colours in the garden", "vocab": "red = लाल\ngreen = हरा\nyellow = पीला\nblue = नीला\npink = गुलाबी"}'::jsonb),
  ('lessons/ex-s3', '{"body": "Count the flowers with Bloom. Hold up one finger for each number.", "courseId": "ex-seeds", "kind": "song", "mediaUrl": "", "minutes": 10, "order": 3, "title": "Count the flowers", "vocab": "one = एक\ntwo = दो\nthree = तीन\nfour = चार\nfive = पाँच"}'::jsonb)
